def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        safe = DAILY_SALARY * 0.28
        if hp <= 2 or no_water >= 1:
            safe = DAILY_SALARY * 0.55
        return float(min(budget, safe))

    prev_bids = []
    aggressive_count = 0
    all_in_count = 0
    fixed_high_count = 0
    weak_opp_count = 0

    for opp in alive_opponents:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            weak_opp_count += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= DAILY_SALARY * 0.75:
                aggressive_count += 1
            if bid >= DAILY_SALARY * 1.4:
                all_in_count += 1
            if bid >= 140:
                fixed_high_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_prev = 0.0
    if prev_bids:
        filtered = [b for b in prev_bids if b < 120]
        moderate_prev = max(filtered) if filtered else min(highest_prev, DAILY_SALARY)

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    base = DAILY_SALARY * (0.34 + 0.18 * scarcity)

    if supply >= 23:
        base -= 8
    elif supply <= 17:
        base += 8

    if hp <= 2:
        bid = DAILY_SALARY * 0.96
    elif no_water >= 2:
        bid = DAILY_SALARY * 0.98
    elif hp <= 4 or no_water >= 1:
        bid = max(DAILY_SALARY * 0.72, moderate_prev + 2.0)
    else:
        if all_in_count >= 1:
            bid = max(base, DAILY_SALARY * 0.42)
        elif aggressive_count >= 2:
            bid = max(base + 4, moderate_prev + 1.5)
        elif aggressive_count == 1:
            bid = max(base, moderate_prev + 1.0)
        else:
            bid = max(base, moderate_prev * 0.92)

    if fixed_high_count >= 1 and hp > 4 and no_water == 0:
        bid = min(bid, DAILY_SALARY * 0.58)

    if weak_opp_count >= 2 and hp > 4 and no_water == 0:
        bid = min(bid, DAILY_SALARY * 0.5)

    if day >= 8:
        bid += 4
    if day >= 9 and (hp <= 4 or no_water >= 1):
        bid += 8

    reserve_floor = 0.0
    days_left = max(0, 10 - int(day))
    if hp > 4 and no_water == 0 and days_left > 1:
        reserve_floor = DAILY_SALARY * 0.35 * min(days_left - 1, 3)

    affordable = max(0.0, budget - reserve_floor)
    if affordable <= 0:
        affordable = min(budget, DAILY_SALARY * 0.4)

    bid = min(bid, affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    budget = my_status['budget']
    hp = my_status['hp']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, 10.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 80.0

    if hp <= 3:
        bid = min(budget, avg_prev_bid * 1.2)
    elif supply < WATER_REQ * len(alive_opponents) * 0.8:
        bid = min(budget, avg_prev_bid * 1.1)
    else:
        bid = min(budget, avg_prev_bid * 0.95)

    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    my_hp = int(my_status['hp'])
    my_budget = my_status['budget']
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = {aid: opp for aid, opp in opponents_status.items() if opp['alive']}

    # Estimate opponents' bids today from their previous trace (yesterday's bid)
    estimated_bids = []
    for aid, opp in alive_opponents.items():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            estimated_bids.append(prev['bid'])

    # Base bid: enough to get water, scale with supply tightness
    if supply <= 16:
        base_bid = min(my_budget, DAILY_SALARY * 0.95)
    elif supply >= 22:
        base_bid = min(my_budget, DAILY_SALARY * 0.4)
    else:
        base_bid = min(my_budget, DAILY_SALARY * 0.65)

    # Adjust based on HP
    if my_hp <= 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.85)
    elif my_hp <= 4:
        base_bid = max(base_bid, DAILY_SALARY * 0.6)

    # If no water for 2+ days, raise bid
    if no_water_days >= 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)

    # Counter strong opponents: ensure we beat the maximum estimated bid if needed
    if estimated_bids:
        highest_est = max(estimated_bids)
        # Cindy bids exactly 147 every day; if she's present, we need to beat 147
        # We'll add a margin of 1 if we can afford it and if we are desperate
        if highest_est >= DAILY_SALARY * 0.85:
            # Aggressive opponent: match or beat by a small margin
            target = highest_est + 1.0
            if my_hp > 5 and supply >= 20:
                # can afford to be conservative, just slightly above
                base_bid = max(base_bid, min(my_budget, highest_est + 0.5))
            else:
                base_bid = max(base_bid, min(my_budget, target))
        else:
            # Opponents moderate: bid slightly above highest estimate
            base_bid = max(base_bid, min(my_budget, highest_est + 1.5))

    # Final clamp to budget
    final_bid = min(my_budget, base_bid)
    # Ensure positive and integer-ish (but Python float ok, will round in game? keep as float)
    return final_bid
